public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    var formatSpan = format.AsSpan();

    if (TryMatchUnit(formatSpan, TerabyteSymbol, out var numFmt))
        return Terabytes.ToString(numFmt, formatProvider) + TerabyteSymbol;
    if (TryMatchUnit(formatSpan, GigabyteSymbol, out numFmt))
        return Gigabytes.ToString(numFmt, formatProvider) + GigabyteSymbol;
    if (TryMatchUnit(formatSpan, MegabyteSymbol, out numFmt))
        return Megabytes.ToString(numFmt, formatProvider) + MegabyteSymbol;
    if (TryMatchUnit(formatSpan, KilobyteSymbol, out numFmt))
        return Kilobytes.ToString(numFmt, formatProvider) + KilobyteSymbol;
    if (TryMatchUnit(formatSpan, ByteSymbol, out numFmt))
        return Bytes.ToString(numFmt, formatProvider) + ByteSymbol;
    if (TryMatchUnit(formatSpan, BitSymbol, out numFmt))
